from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with shared memory and loop unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tiles into shared memory
        int tile_offset = tile * TILE_SIZE;
        int load_row = tile_offset + threadIdx.y;
        int load_col = tile_offset + threadIdx.x;

        if (row < N && load_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + load_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (load_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[load_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with loop unrolling
        int k = 0;
        #pragma unroll
        for (int unroll = 0; unroll < TILE_SIZE/UNROLL_FACTOR; unroll++) {
            for (int i = 0; i < UNROLL_FACTOR; i++) {
                sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
                k++;
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, (N + block_size.y - 1) / block_size.y);

    matmul_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B);"

